def stroke(points, weight=1):
    nib = [(-140, 16), (-72, -46), (100, -67), (140, -16), (72, 46), (-100, 67)]

    def face(p):
        x, y = p
        width = 0.94 + 0.2 * math.cos(2 * math.pi * y / 1110)
        return [(x + dx * weight * width, y + dy * weight) for dx, dy in nib]
    return unary_union([MultiPoint(face(p) + face(q)).convex_hull for p, q in zip(points, points[1:]) if p != q])

def draw(ch, paths=PATHS, stroke_fn=stroke, dot_y=1315, dot_scale=1):
    shapes = []
    for svg in paths.get(ch, []):
        pen = FlattenPen(step=7)
        parse_path(svg, pen)
        for points in pen.contours:
            shapes.append(stroke_fn(points, 1.04 if ch.isupper() else 1))

    def dot(x, y):
        return Polygon([(x + dx * dot_scale, y + dy * dot_scale) for dx, dy in [(-88, -35), (38, 100), (98, 30), (-28, -92)]])
    if ch in 'ij':
        shapes.append(dot(215 if ch == 'i' else 335, dot_y))
    if ch in '.:;!?':
        x = 245 if ch == '!' else 345 if ch == '?' else 160
        shapes.append(dot(x, 105))
        if ch in ':;':
            shapes.append(dot(x + 15, 790))
    if ch in ',;':
        shapes.append(stroke_fn([(205, 155), (175, -35), (65, -170)], 0.8))
    if ch in ['“', '”', '„']:
        y = -100 if ch == '„' else 1330
        direction = 1 if ch == '“' else -1
        for x in [180, 510]:
            shapes.append(stroke_fn([(x + direction * 70, y + 100), (x, y), (x + direction * 55, y - 170)], 0.85))
    if not shapes:
        return GeometryCollection()
    return affinity.skew(unary_union(shapes).buffer(0), 1, 0, origin=(0, 0)).simplify(0.8, preserve_topology=True)
